"""영상 아래에서 분석 결과를 읽고 비교 범위를 바꾸는 간결한 열람 화면."""
from pathlib import Path
import json,re,sys
import pandas as pd
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from src.data_source import sha256_file as sha
W=ROOT/'outputs/private/late_research_design_20261106';B=W/'icy_road_model'
def main():
    p=B/'demo/index.html';s=p.read_text('utf8');assert 'id="analysisResults"' not in s
    s=s.replace('<h1>지도에서 현장 확인 계획까지</h1><p>약 92초의 실제 로컬 실행 화면입니다. 장면을 선택하면 해당 시점부터 재생합니다.</p>',
        '<h1>분석 결과와 실행 영상</h1><p>노면온도 추정 결과와 추가 계측이 필요한 구간을 살펴보세요.</p><nav class="page-jumps" aria-label="이 페이지에서 확인할 내용"><a href="#demoVideoSection">실행 영상</a><a href="#analysisResults">핵심 분석 결과</a><a href="../report/analysis_report.pdf">분석 보고서</a></nav>')
    s=s.replace('<main><div class="demo-layout">','<main id="mainContent"><section id="demoVideoSection"><div class="demo-layout">')
    s=s.replace('<body><header>','<body><a class="skip" href="#mainContent">본문으로 이동</a><header>')
    s=s.replace('음성 없이 화면과 하단 설명으로 구성했습니다. 직접 탐색할 화면과 문자 설명도 함께 제공합니다.','영상은 화면과 자막으로 진행됩니다.')
    labels={'분석 기상 지도':'두 겨울의 기상 지도','같은 관측쌍의 온도 비교':'같은 자료로 온도 오차 비교','결빙 판정과 한계':'결빙 판정과 오경보','공개 목록과 추가 후보':'기존 목록과 추가 계측 후보','목록과 기상 조건의 관계':'기존 목록과 우리 기준 비교','75개 기준의 민감도':'선정 기준을 바꿔 보기','현장 확인과 비교 기록':'현장에서 확인할 항목','전체 기간의 실제 추론':'전체 기간의 예측 다시 실행'}
    for a,b in labels.items():s=s.replace(a,b)
    s=s.replace('<h2>필요한 장면부터 보기</h2>','<h2>장면 선택</h2>')
    # Short, self-contained sections replace a long enumeration of technical subjects.
    metrics=pd.read_csv(B/'results/evaluation/temperature_benchmarks/metrics.csv',float_precision='round_trip')
    names=['asos_air_reference','aws_air_reference','asos_ground_reference','weather12_regression','estimated']
    plot={}
    for scope in ['all_temperature','near_freezing_observed_pm2c']:
        q=metrics.loc[metrics.temperature_scope.eq(scope)&metrics.period.eq('all')&metrics.station.eq('station_macro')].set_index('method')
        plot[scope]=dict(n=int(q.loc['estimated','n']),values=[float(q.loc[name,'mae']) for name in names],gain=float((1-q.loc['estimated','mae']/q.loc['weather12_regression','mae'])*100))
    blocks='''</section><section id="analysisResults" class="analysis-reader"><h2>핵심 분석 결과</h2><p class="reader-intro">관심 있는 주제를 선택하면 결과와 근거를 함께 볼 수 있습니다.</p><div class="reader-tabs" role="tablist" aria-label="분석 주제"><button type="button" role="tab" id="tab-temperature" aria-controls="temperature-results" aria-selected="true">온도 추정</button><button type="button" role="tab" id="tab-icing" aria-controls="icing-results" aria-selected="false" tabindex="-1">결빙 판정</button><button type="button" role="tab" id="tab-sections" aria-controls="section-results" aria-selected="false" tabindex="-1">구간 확인</button></div>
    <div id="temperature-results" class="reader-panel" role="tabpanel" aria-labelledby="tab-temperature"><h3>같은 자료에서 기본 모형보다 온도 오차가 줄었습니다</h3><div class="reader-grid"><div><label for="comparisonScope">비교할 온도 범위</label><select id="comparisonScope"><option value="all_temperature">전체 온도</option><option value="near_freezing_observed_pm2c">0°C 주변: 관측 -2°C부터 +2°C</option></select><p id="comparisonCaption" class="plot-caption" aria-live="polite"></p><div id="comparisonBars" aria-label="온도 모형별 평균 절대오차 비교"></div><div class="plot-axis"><span>0</span><span>3°C</span></div><p class="plot-caption">오차가 작을수록 관측온도에 가깝습니다.</p></div><div><p class="result-sentence" id="comparisonMessage"></p><p>기본 모형은 12개, 현재 모형은 기상 이력과 태양위치 등을 포함한 63개 입력을 사용합니다.</p><p>학습에 쓰지 않은 3지점에서 시험했습니다. 위 비교에는 관측값과 각 모형의 추정값이 모두 있는 같은 시각의 자료만 사용했습니다.</p><div class="actions"><a href="../results/evaluation/temperature_benchmarks/metrics.csv">온도 비교 원표 CSV</a><a href="../report/analysis_report.pdf#page=3">보고서 3-4쪽</a></div></div></div></div>
    <div id="icing-results" class="reader-panel" role="tabpanel" aria-labelledby="tab-icing" hidden><h3>오경보가 많아 추가 확인이 필요합니다</h3><div class="reader-grid"><dl class="metric-definitions"><div><dt>정밀도 <span>Precision</span></dt><dd><strong>0.0195</strong><p>결빙으로 판정한 시각 중 실제 Ice가 있었던 비율</p></dd></div><div><dt>재현율 <span>Recall</span></dt><dd><strong>0.5936</strong><p>실제 Ice가 있었던 시각 중 판정이 잡아낸 비율</p></dd></div><div><dt>F1</dt><dd><strong>0.0326</strong><p>정밀도와 재현율을 함께 보는 지표</p></dd></div></dl><div><p>실제 Ice는 부곡교의 64시점, 19일에 관측됐습니다. 결빙이 관측되지 않은 다른 2지점은 공식 답변에 따라 지표 평균에서 제외했습니다.</p><p>왼쪽 값은 날짜별 지표의 평균입니다. 전체 시점을 한꺼번에 센 비율과는 다릅니다.</p><p class="reader-callout">현재 판정만으로 자동 경보를 내리기에는 근거가 부족합니다. 실제 노면수분과 제빙 이력을 함께 확인해야 합니다.</p><div class="actions"><a href="../index.html#classification">관측 결빙일과 판정일</a><a href="../report/analysis_report.pdf#page=6">보고서 6-7쪽</a></div></div></div></div>
    <div id="section-results" class="reader-panel" role="tabpanel" aria-labelledby="tab-sections" hidden><h3>서해안의 두 범위를 추가 계측 후보로 정리했습니다</h3><div class="reader-grid"><figure><a href="../report/figures/inspection_locations.svg"><img src="../report/figures/inspection_locations.svg" width="900" height="320" loading="lazy" alt="서해안의 추가 계측 범위와 공개 취약구간 비교. 그림을 누르면 확대됩니다."></a><figcaption>추정 이정으로 연결한 범위입니다. 그림을 누르면 확대할 수 있습니다.</figcaption></figure><div><dl class="area-facts"><div><dt>서해안 79.81-80.84km</dt><dd>500m 보고구간 2개 / 분석 길이 1.0km<br>75개 기준 조합 중 60개에서 유지(80%)<br><a href="../results/field/index.html#S01">위치와 비교 계측 항목</a></dd></div><div><dt>서해안 84.28-84.81km</dt><dd>500m 보고구간 1개 / 분석 길이 0.5km<br>75개 기준 조합 중 48개에서 유지(64%)<br><a href="../results/field/index.html#S02">위치와 비교 계측 항목</a></dd></div></dl><p class="plot-caption">유지 비율은 기준을 바꿨을 때 남은 횟수이며 결빙확률이 아닙니다. 실제 위치 확인과 계측은 수행 전입니다.</p></div></div><p>기존 취약구간 목록과 겹칠 수 있는 81구간은 지도에 계속 표시합니다. 추가 후보 3구간을 제안한 결과로 기존 지정을 해제하거나 관리를 줄이지 않습니다.</p><div class="actions"><a class="button" href="../maps/sections.html">구간을 바꾸며 지도 확인</a><a href="../results/field/index.html">현장 확인 계획과 기록 양식</a></div></div></section>'''
    s=s.replace('<details class="transcript">',blocks+'<details class="transcript">',1)
    css='''p,li,dd,dt,figcaption,button{word-break:keep-all;overflow-wrap:break-word;line-break:strict}p{ text-wrap:pretty }h1,h2,h3{text-wrap:balance}.skip{position:absolute;top:-80px;left:20px;z-index:5;background:white;padding:12px}.skip:focus{top:10px}.page-jumps{display:flex;flex-wrap:wrap;gap:14px 24px;margin:19px 0 0}.page-jumps a{font-size:13px}.reader-panel[hidden]{display:none!important}.analysis-reader{border-top:2px solid var(--blue);margin:35px 0 0;padding:28px 0}.analysis-reader>h2{font-size:23px}.reader-intro{color:var(--muted);font-size:14px}.reader-tabs{display:flex;gap:8px;border-bottom:1px solid var(--line);margin:22px 0}.reader-tabs button{border:0;border-radius:0;padding:12px 20px;font-size:15px;min-height:46px}.reader-tabs button[aria-selected=true]{border-bottom:3px solid var(--blue);font-weight:700;background:#eff5f7}.reader-panel{scroll-margin-top:18px}.reader-panel h3{font-size:20px;margin:0 0 20px}.reader-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:42px;align-items:start}.reader-grid>div{min-width:0}.reader-panel p{font-size:15px;line-height:1.9;margin-bottom:14px;max-width:none}.reader-panel .result-sentence{font-size:20px;line-height:1.8;font-weight:700;color:var(--blue);padding-top:23px}.reader-panel label{font-size:13px}#comparisonScope{max-width:330px;margin:8px 0 15px}.plot-row{display:grid;grid-template-columns:125px minmax(0,1fr) 48px;gap:10px;align-items:center;margin:13px 0;font-size:13px}.plot-row strong{text-align:right;font-variant-numeric:tabular-nums}.plot-track{height:16px;background:#f0f4f6}.plot-track i{height:100%;display:block;background:#b5c7cf}.plot-row.current .plot-track i{background:var(--blue)}.plot-axis{display:flex;justify-content:space-between;margin-left:135px;padding-right:58px;font-size:11px;color:var(--muted)}.reader-panel .plot-caption{font-size:12px;line-height:1.8;color:var(--muted);margin-top:12px}.reader-callout{background:#f6f4f0;border-left:3px solid #95652f;padding:12px 15px}.metric-definitions{margin:0}.metric-definitions>div{display:grid;grid-template-columns:110px minmax(0,1fr);padding:14px 0;border-top:1px solid var(--line);gap:18px}.metric-definitions dt{font-size:14px;font-weight:700}.metric-definitions dt span{font-size:12px;color:var(--muted);display:block;font-weight:400}.metric-definitions dd{margin:0}.metric-definitions strong{font-size:22px;font-variant-numeric:tabular-nums;color:var(--blue)}.metric-definitions dd p{font-size:13px;margin:5px 0 0}.reader-panel figure{margin:0}.reader-panel figure img{width:100%;height:auto;display:block}.reader-panel figcaption{font-size:12px;color:var(--muted);margin-top:12px}.area-facts{margin:0}.area-facts>div{border-top:1px solid var(--line);padding:15px 0}.area-facts dt{font-size:17px;font-weight:700}.area-facts dd{font-size:14px;margin:8px 0;line-height:1.9}.chapters button{display:grid;grid-template-columns:38px minmax(0,1fr);gap:10px;min-height:30px;line-height:1.8}.chapters button span{font-variant-numeric:tabular-nums}.transcript{max-width:none}.transcript p{max-width:70em}.video-note{max-width:none}.reader-tabs button:focus-visible{outline:3px solid #80b8cb;outline-offset:2px}button{touch-action:manipulation}@media(max-width:800px){.reader-grid{grid-template-columns:1fr;gap:24px}.reader-panel .result-sentence{padding-top:0}.reader-panel h3{font-size:19px}.reader-panel p{font-size:14px}.reader-tabs button{padding:11px 15px;font-size:14px}.analysis-reader{margin-top:28px;padding-top:24px}.plot-row{grid-template-columns:120px minmax(0,1fr) 45px;gap:7px}.plot-axis{margin-left:127px;padding-right:52px}}
    '''
    s=s.replace('</style>',css+'</style>')
    js='''const compareData=__PLOT__,plotLabels=['ASOS 기온','가까운 AWS 기온','ASOS 지면온도','기본 온도 모형','현재 온도 모형'];function drawComparison(){const d=compareData[document.getElementById('comparisonScope').value];document.getElementById('comparisonCaption').textContent='같은 시각의 자료 '+d.n.toLocaleString('ko-KR')+'개 / 평균 절대오차(MAE), °C';document.getElementById('comparisonBars').innerHTML=d.values.map((v,i)=>'<div class="plot-row '+(i===4?'current':'')+'"><span>'+plotLabels[i]+'</span><div class="plot-track"><i style="width:'+(v/3*100)+'%"></i></div><strong>'+v.toFixed(3)+'</strong></div>').join('');document.getElementById('comparisonMessage').textContent='현재 모형의 오차가 기본 모형보다 '+d.gain.toFixed(1)+'% 낮았습니다.'}document.getElementById('comparisonScope').addEventListener('change',drawComparison);drawComparison();const readerTabs=[...document.querySelectorAll('[role=tab]')];function selectResult(tab,focus){readerTabs.forEach(t=>{const on=t===tab;t.setAttribute('aria-selected',String(on));t.tabIndex=on?0:-1;document.getElementById(t.getAttribute('aria-controls')).hidden=!on});if(focus)tab.focus();try{history.replaceState(null,'','#'+tab.getAttribute('aria-controls'))}catch(e){}}readerTabs.forEach((tab,i)=>{tab.addEventListener('click',()=>selectResult(tab,false));tab.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%readerTabs.length;else if(e.key==='ArrowLeft')next=(i+readerTabs.length-1)%readerTabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=readerTabs.length-1;else return;e.preventDefault();selectResult(readerTabs[next],true)})});if(location.hash){const t=readerTabs.find(t=>'#'+t.getAttribute('aria-controls')===location.hash);if(t)selectResult(t,false)}window.READER_READY=true;'''.replace('__PLOT__',json.dumps(plot,separators=(',',':')))
    s=s.replace('window.DEMO_READY=true;','window.DEMO_READY=true;'+js)
    p.write_text(s,'utf8')
    record=dict(status='built_pending_checks',scope='same demo/index.html requested by user',wording='short headings and paragraphs; Korean word-break keep-all; balanced headings; results in three native keyboard tabs',
        comparison_source_sha256=sha(B/'results/evaluation/temperature_benchmarks/metrics.csv'),
        references=['https://dribbble.com/shots/26240563--Clima-dashboard','https://dribbble.com/shots/27400006-Weather-Monitoring-Dashboard','https://designsystem.digital.gov/components/typography/','https://github.com/vercel-labs/agent-skills/tree/main/skills/web-design-guidelines'],
        references_applied='compare datasets in one view, keep geographic context, give each module one purpose; original artwork and mock data not copied',
        original_full_resolution_dribbble_assets_unavailable=True)
    (W/'reader_build.json').write_text(json.dumps(record,ensure_ascii=False,indent=2)+'\n','utf8')
    print('Built readable demo analysis panels, short copy and Korean word wrapping',flush=True)
if __name__=='__main__':main()
